public class METSalesOrderLineDualWriteUpdate extends METBatchMultipleThreadBase implements BatchRetryable
{
    Integer             numOfRecords;
    DialogField         dlgNumOfRecords;

    PositiveNumber      maxTaskCount;
    DialogField         dlgMaxTaskCount;

    QueryRun            queryRun;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        numOfRecords,
        maxTaskCount,
        batchIdentifier
    #endmacro

}

Method.Source:
public Object dialog()
{
    DialogRunbase       dialog = super();

    dlgNumOfRecords     = dialog.addFieldValue(extendedtypestr(Integer), numOfRecords, "@MET:SalesOrderLineDualWriteUpdateNumOfRecords", "@MET:SalesOrderLineDualWriteUpdateNumOfRecordsHelp");
    dlgNumOfRecords.enabled(false);

    dialog.addGroup("@MET:SalesOrderLineDualWriteUpdatePerformanceSettings");
    dlgMaxTaskCount     = dialog.addFieldValue(extendedtypestr(PositiveNumber), maxTaskCount, "@MET:SalesOrderLineDualWriteUpdateMaxTaskCount", "@MET:SalesOrderLineDualWriteUpdateMaxTaskCountHelp");

    return dialog;
}

public boolean getFromDialog()
{
    maxTaskCount = dlgMaxTaskCount.value();

    return super();
}

public void initQuery()
{
    Query                   query = new Query();
    QueryBuildDataSource    qbds = query.addDataSource(tablenum(METSalesLine));
    QueryBuildRange         qBR;

    qBR = SysQuery::findOrCreateRange(qbds, fieldnum(METSalesLine, DualWriteRequired));
    qBR.value(queryValue(NoYes::Yes));
    qBR.status(RangeStatus::Locked);

    queryRun = new QueryRun(query);
}

public void calcNumOfRecords()
{
    numOfRecords = SysQuery::countTotal(new QueryRun(queryRun.query()));
}

public boolean unpack(container _packedClass)
{
    Version    version = RunBase::getVersion(_packedClass);
    container  queryCon;
    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList, queryCon] = _packedClass;
            if (SysQuery::isPackedOk(queryCon))
            {
                queryRun = new QueryRun(queryCon);
            }
            else
            {
                this.initQuery();
            }
            break;
        default:
            return false;
    }
    return true;
}

public void runThreadTask()
{
    int                     processedCounter;
    METSalesLine            metSalesLine, metSalesLineUpdate;
    QueryBuildDataSource    qbds = queryRun.query().dataSourceTable(tablenum(METSalesLine));

    qbds.addRange(fieldnum(METSalesLine, RecId)).value(batchIdentifier);

    while (queryRun.next())
    {
        metSalesLine = queryRun.get(tablenum(METSalesLine));

        try
        {
            ttsbegin;

            select firstonly forupdate metSalesLineUpdate
                where metSalesLineUpdate.RecId == metSalesLine.RecId;

            if (metSalesLineUpdate && metSalesLineUpdate.DualWriteRequired == NoYes::Yes)
            {
                metSalesLineUpdate.DualWriteRequired = NoYes::No;
                metSalesLineUpdate.update();
            }

            ttscommit;

            processedCounter++;
        }
        catch (Exception::Error)
        {
            error(strFmt("@MET:SalesOrderLineDualWriteUpdateErrorFailed", metSalesLine.salesLine().SalesId, metSalesLine.RecId));
        }
        catch (Exception::Deadlock)
        {
            error(strFmt("@MET:SalesOrderLineDualWriteUpdateErrorDeadlock", metSalesLine.salesLine().SalesId, metSalesLine.RecId));
        }
        catch (Exception::UpdateConflict)
        {
            error(strFmt("@MET:SalesOrderLineDualWriteUpdateErrorUpdateConflict", metSalesLine.salesLine().SalesId, metSalesLine.RecId));
        }
    }

    info(strFmt("@MET:SalesOrderLineDualWriteUpdateThreadProcessed", processedCounter, batchIdentifier));
}

public void runFinalTask()
{
    int remaining;

    remaining = SysQuery::countTotal(queryRun);

    info(strFmt("@MET:SalesOrderLineDualWriteUpdateFinal", remaining));
}

public container getBatchIdentifiersRangeCon()
{
    container  res;
    QueryRun   queryRunLocal = new QueryRun(queryRun.query());

    QueryBuildDataSource   qBDS = queryRunLocal.query().dataSourceTable(tablenum(METSalesLine));
    int                    totalRecords, curRecord, recordsPerBatch;
    RecId                  fromRecId, toRecId;

    qBDS.sortClear();
    qBDS.addSortField(fieldnum(METSalesLine, RecId));

    totalRecords = SysQuery::countTotal(queryRunLocal);
    recordsPerBatch = maxTaskCount > 0 ? totalRecords div maxTaskCount : totalRecords;
    if (! recordsPerBatch)
    {
        recordsPerBatch = 1;
    }

    while (queryRunLocal.next())
    {
        METSalesLine metSalesLine = queryRunLocal.get(tablenum(METSalesLine));
        if (! fromRecId)
        {
            fromRecId = metSalesLine.RecId;
        }
        curRecord++;
        toRecId = metSalesLine.RecId;
        if ((curRecord mod recordsPerBatch) == 0)
        {
            res += SysQuery::range(fromRecId, toRecId);
            fromRecId = 0;
            curRecord = 0;
        }
    }
    if (curRecord && fromRecId && toRecId)
    {
        res += SysQuery::range(fromRecId, toRecId);
    }

    return res;
}

public static METSalesOrderLineDualWriteUpdate construct()
{
    return new METSalesOrderLineDualWriteUpdate();
}

public static void main(Args _args)
{
    METSalesOrderLineDualWriteUpdate runObject = METSalesOrderLineDualWriteUpdate::construct();

    if (runObject.prompt())
    {
        runObject.runOperation();
    }
}
